const LEVELS = {
    'easy': { name: 'スライム', hp: 10, sprite: '<img src="slime.png" alt="スライム" class="monster-img">' },
    'normal': { name: 'ゴーレム', hp: 10, sprite: '<img src="golem.png" alt="ゴーレム" class="monster-img">' },
    'hard': { name: 'キマイラ', hp: 10, sprite: '<img src="chimera.png" alt="キマイラ" class="monster-img">' },
    'super-hard': { name: 'まおう', hp: 10, sprite: '<img src="demon_lord.png" alt="まおう" class="monster-img">' }
};

const state = {
    level: 'easy',
    playerHP: 3,
    playerMaxHP: 3,
    enemyHP: 10,
    currentCorrectAnswer: 0,
    timerInterval: null,
    timeLeft: 100, // 現在の残り時間
    maxTime: 100,  // 現在の問題の最大制限時間
    isAnswering: false
};

// DOM要素
const screens = {
    title: document.getElementById('title-screen'),
    levelSelect: document.getElementById('level-select-screen'),
    battle: document.getElementById('battle-screen'),
    result: document.getElementById('result-screen')
};

const elPlayerHP = document.getElementById('player-hp');
const elEnemyHP = document.getElementById('enemy-hp');
const elEnemyName = document.getElementById('enemy-name');
const elEnemySprite = document.getElementById('enemy-sprite');
const elMessageArea = document.getElementById('message-area');
const elQuestionArea = document.getElementById('question-area');
const elChoicesArea = document.getElementById('choices-area');
const elTimerBar = document.getElementById('timer-bar');
const elResultTitle = document.getElementById('result-title');
const elResultMessage = document.getElementById('result-message');
const elGameContainer = document.getElementById('game-container');

// 初期化
function init() {
    document.body.className = 'bg-title'; // タイトル画面の背景設定
    
    document.getElementById('btn-start').addEventListener('click', () => showScreen('levelSelect'));
    
    // レベル選択ボタン
    document.querySelectorAll('.btn-level').forEach(btn => {
        btn.addEventListener('click', (e) => {
            startGame(e.target.getAttribute('data-level'));
        });
    });

    // 選択肢ボタン (タッチ/クリック両対応)
    document.querySelectorAll('.btn-choice').forEach(btn => {
        btn.addEventListener('click', (e) => {
            if (!state.isAnswering) return;
            handleAnswer(parseInt(e.target.textContent));
        });
    });

    document.getElementById('btn-next-question').addEventListener('click', () => {
        nextTurn();
    });

    document.getElementById('btn-return-title').addEventListener('click', () => {
        document.body.className = 'bg-title';
        showScreen('title');
    });
}

function showScreen(screenName) {
    Object.values(screens).forEach(el => el.classList.remove('active'));
    screens[screenName].classList.add('active');
}

function startGame(levelKey) {
    state.level = levelKey;
    state.playerHP = state.playerMaxHP;
    const enemyData = LEVELS[levelKey];
    state.enemyHP = enemyData.hp;

    // ダンジョンの背景をレベルに合わせて変える
    document.body.className = 'bg-' + levelKey;

    elEnemyName.textContent = enemyData.name;
    elEnemySprite.innerHTML = enemyData.sprite;
    updateStatus();

    showScreen('battle');
    
    elMessageArea.style.display = 'block';
    elMessageArea.textContent = `${enemyData.name} が あらわれた！`;
    elQuestionArea.style.display = 'none';
    elChoicesArea.style.display = 'none';
    document.getElementById('btn-next-question').style.display = 'none';
    
    setTimeout(() => {
        nextTurn();
    }, 1500);
}

function updateStatus() {
    elPlayerHP.textContent = state.playerHP;
    elEnemyHP.textContent = state.enemyHP;
}

function nextTurn() {
    if (state.playerHP <= 0 || state.enemyHP <= 0) return;

    document.getElementById('btn-next-question').style.display = 'none';
    elMessageArea.style.display = 'none';
    elQuestionArea.style.display = 'block';
    elChoicesArea.style.display = 'flex';
    
    // 問題を生成
    const q = generateQuestion();
    state.currentCorrectAnswer = q.answer;
    elQuestionArea.textContent = q.text;

    // 選択肢を生成
    const choices = generateChoices(q.answer, q.progress);
    const choiceButtons = document.querySelectorAll('.btn-choice');
    choices.forEach((num, index) => {
        choiceButtons[index].textContent = num;
        choiceButtons[index].disabled = false;
    });

    state.isAnswering = true;
    startTimer();
}

function getRandom(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

function generateQuestion() {
    let num1, num2, operator;
    let progress = 11 - state.enemyHP; // 1〜10

    if (state.level === 'easy') {
        if (progress <= 3) {
            num1 = getRandom(1, 5);
            num2 = getRandom(1, 5);
            operator = '+';
        } else if (progress <= 6) {
            num1 = getRandom(2, 9);
            num2 = getRandom(2, 9);
            operator = '+';
        } else if (progress <= 8) {
            num1 = getRandom(11, 19);
            num2 = getRandom(1, num1 % 10 === 0 ? 1 : num1 % 10); // 繰り下がりなし
            operator = '-';
        } else {
            num1 = getRandom(11, 18);
            num2 = getRandom((num1 % 10) + 1, 9); // 繰り下がりあり
            operator = '-';
        }
    } else if (state.level === 'normal') {
        if (progress <= 3) {
            num1 = getRandom(10, 49);
            num2 = getRandom(1, 9);
            operator = '+';
        } else if (progress <= 6) {
            num1 = getRandom(20, 50);
            num2 = getRandom(1, 9);
            operator = '-';
        } else if (progress <= 8) {
            num1 = getRandom(10, 49);
            num2 = getRandom(10, 49);
            operator = '+';
        } else {
            num1 = getRandom(50, 99);
            num2 = getRandom(10, 49);
            operator = '-';
        }
    } else if (state.level === 'hard') {
        if (progress <= 3) {
            num1 = getRandom(100, 500);
            num2 = getRandom(10, 99);
            operator = '+';
        } else if (progress <= 6) {
            num1 = getRandom(10, 30);
            num2 = getRandom(2, 5);
            operator = '×';
        } else if (progress <= 8) {
            num1 = getRandom(200, 999);
            num2 = getRandom(100, 199);
            operator = '-';
        } else {
            num1 = getRandom(11, 99);
            num2 = getRandom(3, 9);
            operator = '×';
        }
    } else if (state.level === 'super-hard') {
        if (progress <= 3) {
            num1 = getRandom(100, 999);
            num2 = getRandom(100, 999);
            operator = '+';
        } else if (progress <= 6) {
            num1 = getRandom(200, 999);
            num2 = getRandom(100, 199);
            operator = '-';
        } else if (progress <= 8) {
            num1 = getRandom(11, 50);
            num2 = getRandom(11, 20);
            operator = '×';
        } else {
            num1 = getRandom(100, 999);
            num2 = getRandom(3, 9);
            operator = '×';
        }
    }

    let answer;
    if (operator === '+') answer = num1 + num2;
    if (operator === '-') answer = num1 - num2;
    if (operator === '×') answer = num1 * num2; 

    return { text: `${num1} ${operator} ${num2} = ?`, answer: answer, progress: progress };
}

function generateChoices(correctAnswer, progress) {
    let choices = [correctAnswer];
    while(choices.length < 3) {
        let offset;
        // 10問中3問 (例: 4問目, 7問目, 9問目) は、1の位が同じになるように10の倍数でズラす
        if (progress === 4 || progress === 7 || progress === 9) {
            offset = getRandom(1, 5) * 10 * (getRandom(0, 1) === 0 ? 1 : -1);
            if (correctAnswer <= 10) offset = getRandom(1, 3) * 10;
        } else {
            offset = getRandom(1, 10) * (getRandom(0, 1) === 0 ? 1 : -1);
            if (correctAnswer > 100) offset = getRandom(10, 50) * (getRandom(0, 1) === 0 ? 1 : -1);
            if (correctAnswer > 1000) offset = getRandom(100, 500) * (getRandom(0, 1) === 0 ? 1 : -1);
        }
        
        let fake = correctAnswer + offset;
        if (fake <= 0) fake = correctAnswer + Math.abs(offset); 
        if (!choices.includes(fake)) choices.push(fake);
    }
    choices.sort(() => Math.random() - 0.5);
    return choices;
}

function startTimer() {
    // レベルと進行度（敵の減ったHP）に応じてタイマーの初期値を短くする
    let decreaseRate = 3;
    if (state.level === 'normal') decreaseRate = 4;
    if (state.level === 'hard') decreaseRate = 6;
    if (state.level === 'super-hard') decreaseRate = 7;
    
    // 敵HP=10の時 maxTime=100。敵HP=1の時、難易度に応じてmaxTimeが減る。
    state.maxTime = 100 - ((10 - state.enemyHP) * decreaseRate);
    if (state.maxTime < 20) state.maxTime = 20; // どんなに短くても2秒以下にはしない

    state.timeLeft = state.maxTime;
    updateTimerUI();
    
    if (state.timerInterval) clearInterval(state.timerInterval);
    
    state.timerInterval = setInterval(() => {
        state.timeLeft--;
        updateTimerUI();
        
        if (state.timeLeft <= 0) {
            clearInterval(state.timerInterval);
            handleTimeout();
        }
    }, 100);
}

function updateTimerUI() {
    const percentage = (state.timeLeft / state.maxTime) * 100;
    elTimerBar.style.width = percentage + '%';
    
    if (percentage > 50) {
        elTimerBar.style.backgroundColor = '#00ff00';
    } else if (percentage > 25) {
        elTimerBar.style.backgroundColor = '#ffff00';
    } else {
        elTimerBar.style.backgroundColor = '#ff0000';
    }
}

function stopTimer() {
    if (state.timerInterval) clearInterval(state.timerInterval);
}

function handleAnswer(selectedNumber) {
    if (!state.isAnswering) return;
    state.isAnswering = false;
    stopTimer();

    document.querySelectorAll('.btn-choice').forEach(btn => btn.disabled = true);

    if (selectedNumber === state.currentCorrectAnswer) {
        state.enemyHP--;
        updateStatus();
        
        elEnemySprite.classList.add('anim-flash-enemy');
        setTimeout(() => elEnemySprite.classList.remove('anim-flash-enemy'), 400);

        showMessage(`せいかい！ ${LEVELS[state.level].name} に 1 のダメージ！`);
        
    } else {
        playerDamageMessage();
    }
}

function handleTimeout() {
    if (!state.isAnswering) return;
    state.isAnswering = false;
    
    document.querySelectorAll('.btn-choice').forEach(btn => btn.disabled = true);
    playerDamageMessage(true);
}

function playerDamageMessage(isTimeout = false) {
    state.playerHP--;
    updateStatus();

    elGameContainer.classList.add('anim-shake');
    document.body.classList.add('anim-flash-screen');
    
    setTimeout(() => {
        elGameContainer.classList.remove('anim-shake');
        document.body.classList.remove('anim-flash-screen');
    }, 500);

    const txt = isTimeout ? 'じかんぎれ！' : 'ふせいかい！';
    showMessage(`${txt} ゆうしゃ は 1 のダメージ をうけた！`);
}

function showMessage(text) {
    elQuestionArea.style.display = 'none';
    elChoicesArea.style.display = 'none';
    elMessageArea.style.display = 'block';
    elMessageArea.innerHTML = text;
    
    setTimeout(checkGameEnd, 1500);
}

function checkGameEnd() {
    if (state.playerHP <= 0) {
        elResultTitle.textContent = 'ゲームオーバー...';
        elResultTitle.style.color = '#ff0000';
        elResultMessage.textContent = 'ゆうしゃ は ちからつきた。';
        document.body.className = 'bg-title'; // 背景リセット
        showScreen('result');
    } else if (state.enemyHP <= 0) {
        elResultTitle.textContent = '討伐成功！';
        elResultTitle.style.color = '#ffff00';
        elResultMessage.textContent = `${LEVELS[state.level].name} を やつけました！`;
        document.body.className = 'bg-title'; // 背景リセット
        showScreen('result');
    } else {
        nextTurn();
    }
}



const AI_IMAGES = {
  'easy': '',
  'normal': '',
  'hard': '',
  'super-hard': '',
};

async function preloadImages() {
    for (let key of Object.keys(LEVELS)) {
        if (AI_IMAGES[key]) {
            // Data URIとして認識させる
            const dataUri = 'data:image/png;base64,' + AI_IMAGES[key];
            try {
                // セキュリティエラーを回避して自動切り抜き
                const transSrc = await removeBackgroundFloodFill(dataUri);
                LEVELS[key].sprite = '<img src="' + transSrc + '" alt="' + LEVELS[key].name + '" class="monster-img">';
            } catch (e) {
                console.error("画像透過処理エラー:", e);
                LEVELS[key].sprite = '<img src="' + dataUri + '" alt="' + LEVELS[key].name + '" class="monster-img">';
            }
        }
    }
}

function removeBackgroundFloodFill(src) {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const w = img.width;
            const h = img.height;
            canvas.width = w;
            canvas.height = h;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(img, 0, 0);
            const imageData = ctx.getImageData(0, 0, w, h);
            const data = imageData.data;
            const bgR = data[0];
            const bgG = data[1];
            const bgB = data[2];
            const threshold = 20;
            const isBg = (x, y) => {
                const idx = (y * w + x) * 4;
                return Math.abs(data[idx] - bgR) <= threshold && 
                       Math.abs(data[idx+1] - bgG) <= threshold && 
                       Math.abs(data[idx+2] - bgB) <= threshold && 
                       data[idx+3] > 0;
            };
            const visited = new Uint8Array(w * h);
            const stack = [];
            for(let i=0; i<w; i++) { stack.push([i,0]); stack.push([i,h-1]); }
            for(let j=0; j<h; j++) { stack.push([0,j]); stack.push([w-1,j]); }
            while(stack.length > 0) {
                const pt = stack.pop();
                const x = pt[0], y = pt[1];
                if(x<0||x>=w||y<0||y>=h) continue;
                const idx = y * w + x;
                if(visited[idx]) continue;
                if(isBg(x, y)) {
                    visited[idx] = 1;
                    const pIdx = idx * 4;
                    data[pIdx+3] = 0; 
                    stack.push([x+1, y], [x-1, y], [x, y+1], [x, y-1]);
                }
            }
            ctx.putImageData(imageData, 0, 0);
            resolve(canvas.toDataURL('image/png'));
        };
        img.onerror = reject;
        img.src = src;
    });
}

window.onload = async () => {
    await preloadImages();
    init();
};
